@admin.get("/orders")
async def admin_orders(status: str = "pending"):
    return PDB.query("SELECT o.*, u.email, u.phone, u.name FROM orders o LEFT JOIN users u ON u.id=o.user_id "
                     "WHERE o.status=? ORDER BY o.created_at DESC LIMIT 500", (status,))


@admin.post("/orders/{oid}/approve")
async def approve_order(oid: str):
    o = PDB.get("orders", oid)
    if not o:
        raise HTTPException(404, "Not found")
    if o["status"] == "approved":
        return {"ok": True}
    pid = new_id("pay")
    PDB.insert("payments", {"id": pid, "user_id": o["user_id"], "plan_id": o["plan_id"], "provider": "manual",
                            "provider_ref": o["order_code"], "amount": o["amount"], "currency": o["currency"],
                            "status": "created", "created_at": now_iso()})
    _activate(PDB.get("payments", pid))
    PDB.update("orders", oid, {"status": "approved", "reviewed_at": now_iso()})
    return {"ok": True}


@admin.post("/orders/{oid}/reject")
async def reject_order(oid: str):
    PDB.update("orders", oid, {"status": "rejected", "reviewed_at": now_iso()})
    return {"ok": True}


@admin.delete("/orders/{oid}")
async def delete_order(oid: str):
    return {"deleted": PDB.delete("orders", oid)}


# ============================================================ USER APPROVAL / DELETION
@admin.post("/users/{uid}/approve")
async def approve_user(uid: str):
    PDB.update("users", uid, {"status": "active"})
    return {"ok": True}


@admin.delete("/users/{uid}")
async def delete_user(uid: str, me=Depends(auth.require_admin_user)):
    if uid == me.get("id"):
        raise HTTPException(400, "You cannot delete your own admin account")
    for t, col in (("contacts", "user_id"), ("orders", "user_id"), ("sos_events", "user_id")):
        PDB.execute(f"DELETE FROM {t} WHERE {col}=?", (uid,))
    PDB.execute("DELETE FROM push_user WHERE user_id=?", (uid,))
    return {"deleted": PDB.delete("users", uid)}


