@router.get("/api/programs")
async def programs(lang: str = "en"):
    rows = PDB.query("SELECT * FROM programs WHERE active=1 AND (lang='all' OR lang=? OR lang='en') "
                     "ORDER BY (date_at='' ) , date_at ASC LIMIT 100", (lang,))
    today_s = now_iso()[:10]
    return [r for r in rows if not r["date_at"] or r["date_at"][:10] >= today_s] + \
           [r | {"past": True} for r in rows if r["date_at"] and r["date_at"][:10] < today_s][:6]


