# ================================================================= CONTACTS & SOS
class ContactIn(BaseModel):
    name: str = Field(..., min_length=1, max_length=60)
    phone: str = Field(default="", max_length=30)
    email: str = Field(default="", max_length=200)


@router.get("/api/contacts")
async def list_contacts(user=Depends(require_user)):
    return PDB.query("SELECT * FROM contacts WHERE user_id=? ORDER BY created_at", (user["id"],))


@router.post("/api/contacts")
async def add_contact(body: ContactIn, user=Depends(require_user)):
    if PDB.scalar("SELECT COUNT(*) FROM contacts WHERE user_id=?", (user["id"],)) >= 5:
        raise HTTPException(400, "You can save up to 5 emergency contacts")
    phone = norm_phone(body.phone) if body.phone.strip() else ""
    if body.phone.strip() and not phone:
        raise HTTPException(400, "Invalid phone number")
    email = body.email.strip().lower()
    if email and not checker.EMAIL_RE.match(email):
        raise HTTPException(400, "Invalid email")
    if not phone and not email:
        raise HTTPException(400, "Add a phone number or email")
    cid = new_id("ctc")
    PDB.insert("contacts", {"id": cid, "user_id": user["id"], "name": body.name.strip(), "phone": phone, "email": email,
                            "created_at": now_iso()})
    return PDB.get("contacts", cid)


@router.delete("/api/contacts/{cid}")
async def delete_contact(cid: str, user=Depends(require_user)):
    PDB.execute("DELETE FROM contacts WHERE id=? AND user_id=?", (cid, user["id"]))
    return {"ok": True}


class SosIn(BaseModel):
    kind: str = Field(default="safety", pattern="^(safety|scam|medical)$")
    message: str = Field(default="", max_length=300)
    lat: Optional[float] = Field(default=None, ge=-90, le=90)
    lon: Optional[float] = Field(default=None, ge=-180, le=180)
    accuracy: Optional[float] = Field(default=None, ge=0, le=100000)


SOS_TEXT = {
    "safety": "needs help right now",
    "scam": "is being targeted by a scam right now (call them before they pay or share any code)",
    "medical": "has a medical emergency",
}


@router.post("/api/sos")
async def sos(body: SosIn, request: Request, user=Depends(require_user)):
    _rl(request)
    last = PDB.scalar("SELECT created_at FROM sos_events WHERE user_id=? ORDER BY created_at DESC LIMIT 1", (user["id"],))
    if last and last > (datetime.now(timezone.utc) - timedelta(seconds=60)).isoformat():
        raise HTTPException(429, "SOS already sent less than a minute ago")
    s = PDB.settings()
    who = user.get("name") or (user["phone"] if user.get("phone") else user["email"].split("@")[0])
    maps = f"https://maps.google.com/?q={body.lat:.6f},{body.lon:.6f}" if body.lat is not None and body.lon is not None else ""
    text = f"🚨 SOS from {who} ({s['site_name']}): {who} {SOS_TEXT[body.kind]}."
    if body.message.strip():
        text += f" Message: {body.message.strip()}"
    if maps:
        text += f" Location: {maps}"
    contact_phone = user.get("phone") or ""
    if contact_phone:
        text += f" Call them: {contact_phone}"
    eid = new_id("sos")
    PDB.insert("sos_events", {"id": eid, "user_id": user["id"], "family_code": user.get("family_code") or "", "kind": body.kind,
                              "message": body.message.strip(), "lat": body.lat, "lon": body.lon, "accuracy": body.accuracy,
                              "created_at": now_iso()})
    notified, channels = 0, []
    # 1) push to family members' devices
    if user.get("family_code") and product._push:
        members = [m["id"] for m in PDB.query("SELECT id FROM users WHERE family_code=? AND id!=?", (user["family_code"], user["id"]))]
        if members:
            eps = [r["endpoint"] for r in PDB.query(
                f"SELECT endpoint FROM push_user WHERE user_id IN ({','.join('?' * len(members))})", members)]
            n = await product._push.notify_endpoints(eps, "🚨 SOS — family emergency", text, severity="critical")
            notified += n
            channels.append(f"push:{n}")
    # 2) SMS / email to saved emergency contacts
    contacts = PDB.query("SELECT * FROM contacts WHERE user_id=?", (user["id"],))
    for c in contacts:
        if c["phone"]:
            ok, _ = await asyncio.to_thread(notify.send_sms, s, c["phone"], text)
            notified += int(ok)
            channels.append(f"sms:{c['name']}:{'ok' if ok else 'not-configured'}")
        if c["email"]:
            ok, _ = await asyncio.to_thread(notify.send_email, s, c["email"], f"🚨 SOS from {who}", text)
            notified += int(ok)
            channels.append(f"email:{c['name']}:{'ok' if ok else 'not-configured'}")
    PDB.update("sos_events", eid, {"notified": notified})
    PDB.bump("sos")
    return {"ok": True, "id": eid, "notified": notified, "contacts": len(contacts), "channels": channels,
            "share_text": text, "maps": maps, "emergency_number": s["emergency_number"], "cyber_helpline": s["cyber_helpline"],
            "contact_phones": [c["phone"] for c in contacts if c["phone"]]}


@router.post("/api/sos/{eid}/resolve")
async def sos_resolve(eid: str, user=Depends(require_user)):
    PDB.execute("UPDATE sos_events SET status='resolved' WHERE id=? AND user_id=?", (eid, user["id"]))
    return {"ok": True}


@router.get("/api/sos/family")
async def sos_family(user=Depends(require_user)):
    if not user.get("family_code"):
        rows = PDB.query("SELECT * FROM sos_events WHERE user_id=? ORDER BY created_at DESC LIMIT 20", (user["id"],))
    else:
        rows = PDB.query("SELECT e.*, u.name, u.email, u.phone FROM sos_events e LEFT JOIN users u ON u.id=e.user_id "
                         "WHERE e.family_code=? ORDER BY e.created_at DESC LIMIT 30", (user["family_code"],))
    for r in rows:
        r["maps"] = f"https://maps.google.com/?q={r['lat']:.6f},{r['lon']:.6f}" if r.get("lat") is not None and r.get("lon") is not None else ""
        r.pop("email", None)
    return rows


@admin.get("/sos")
async def admin_sos():
    # Privacy: admin sees counts and timing, never locations or messages.
    return PDB.query("SELECT e.id, e.kind, e.notified, e.status, e.created_at, u.email, u.phone FROM sos_events e "
                     "LEFT JOIN users u ON u.id=e.user_id ORDER BY e.created_at DESC LIMIT 200")


class NotifyTestIn(BaseModel):
    to: str = Field(..., max_length=200)


@admin.post("/notify/test")
async def notify_test(body: NotifyTestIn):
    s = PDB.settings()
    channel, target = identify(body.to)
    if not channel:
        raise HTTPException(400, "Enter a mobile number or email")
    msg = f"Test message from {s['site_name']}. Your login codes and SOS alerts will look like this."
    ok, detail = await asyncio.to_thread(notify.send_email if channel == "email" else notify.send_sms, s, target,
                                         *(("Test message", msg) if channel == "email" else (msg,)))
    return {"ok": ok, "detail": detail, "channel": channel}


