@router.get("/api/fraud-guide")
async def fraud_guide():
    since = (datetime.now(timezone.utc) - timedelta(days=7)).strftime("%Y-%m-%d")
    cat = {r["key"][4:]: r["v"] for r in PDB.query(
        "SELECT key, SUM(value) v FROM stats WHERE key LIKE 'cat_%' AND day>=? GROUP BY key", (since,))}
    prev_since = (datetime.now(timezone.utc) - timedelta(days=14)).strftime("%Y-%m-%d")
    prev = {r["key"][4:]: r["v"] for r in PDB.query(
        "SELECT key, SUM(value) v FROM stats WHERE key LIKE 'cat_%' AND day>=? AND day<? GROUP BY key", (prev_since, since))}
    reports = {r["kind"]: r["c"] for r in PDB.query(
        "SELECT kind, COUNT(*) c FROM reports WHERE created_at>=? GROUP BY kind", (since,))}
    items = []
    for g in FRAUD_GUIDE:
        n = int(cat.get(g["category"], 0))
        items.append({**g, "week_count": n, "trend": "up" if n > prev.get(g["category"], 0) else "flat" if n == prev.get(g["category"], 0) else "down"})
    items.sort(key=lambda x: -x["week_count"])
    return {"items": items, "reports_by_kind": reports, "since": since}


